import re
import subprocess

_SCRIPT = "/opt/billing/jobs/renew_subscriptions.py"
_DATE_RE = re.compile(r"^\d{4}-\d{2}-\d{2}$")
_PLAN_RE = re.compile(r"^[a-z0-9_\-]{2,40}$")


def run_renewal_batch(plan_code, billing_date, dry_run=True):
    if not _PLAN_RE.match(plan_code):
        return {"ok": False, "error": "invalid plan_code"}
    if not _DATE_RE.match(billing_date):
        return {"ok": False, "error": "billing_date must be YYYY-MM-DD"}

    cmd = [
        "python3",
        _SCRIPT,
        "--plan",
        plan_code,
        "--date",
        billing_date,
    ]
    if dry_run:
        cmd.append("--dry-run")

    try:
        proc = subprocess.run(
            cmd,
            capture_output=True,
            text=True,
            timeout=900,
            check=False,
        )
    except subprocess.TimeoutExpired:
        return {"ok": False, "error": "renewal job timed out", "command": cmd}

    return {
        "ok": proc.returncode == 0,
        "exit_code": proc.returncode,
        "dry_run": dry_run,
        "command": cmd,
        "stdout": proc.stdout[-4000:],
        "stderr": proc.stderr[-2000:],
    }

import sqlite3


def grant_subscription_admin(db_path, subscription_id, user_id):
    conn = sqlite3.connect(db_path)
    try:
        row = conn.execute(
            "SELECT role FROM subscription_members WHERE subscription_id = ? AND user_id = ?",
            (subscription_id, user_id),
        ).fetchone()
        if row is None:
            return {"ok": False, "error": "user is not a member of this subscription"}
        conn.execute(
            "UPDATE subscription_members SET role = 'billing_admin' WHERE subscription_id = ? AND user_id = ?",
            (subscription_id, user_id),
        )
        conn.commit()
        return {"ok": True, "previous_role": row[0], "new_role": "billing_admin"}
    finally:
        conn.close()
